{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL threat detection alerts are excluded",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "HIGH",
      "explanation": "The policy explicitly disables SQL injection and data exfiltration alerts, preventing detection of two high-impact attack categories."
    },
    {
      "check_id": "CKV_AZURE_29",
      "title": "Insufficient threat detection alert retention",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "Threat detection records are retained for only 20 days, limiting historical investigation and audit evidence. A minimum retention period of 90 days is recommended."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts            = []\n  retention_days             = 90\n}\n",
  "fix_summary": "Enabled all SQL security alert categories by removing the SQL injection and data exfiltration exclusions. Increased threat detection record retention from 20 to 90 days."
}
